package protocol

import "time"

// CompletionReceipt is generated by the worker when a task finishes execution.
// It contains execution metadata, resource usage stats, and artifact information.
type CompletionReceipt struct {
	// TaskID is the unique task identifier.
	TaskID string `json:"task_id"`

	// JobID groups this task with others.
	JobID string `json:"job_id"`

	// WorkerID identifies which worker executed the task.
	WorkerID string `json:"worker_id"`

	// ExitCode is the process exit code (0 = success).
	ExitCode int `json:"exit_code"`

	// Status is the final task status.
	Status TaskStatus `json:"status"`

	// WallClockDurationMs is the total execution time in milliseconds.
	WallClockDurationMs int64 `json:"wall_clock_duration_ms"`

	// ResourceUsage reports CPU, memory, and I/O consumed.
	ResourceUsage ResourceUsage `json:"resource_usage"`

	// ArtifactBundle describes the output artifact (if any).
	ArtifactBundle *ArtifactBundle `json:"artifact_bundle,omitempty"`

	// ErrorMessage contains the error description if the task failed.
	ErrorMessage string `json:"error_message,omitempty"`

	// StartedAt is when execution began.
	StartedAt time.Time `json:"started_at"`

	// CompletedAt is when execution finished.
	CompletedAt time.Time `json:"completed_at"`

	// StreamStats reports Channel A streaming statistics.
	StreamStats StreamStats `json:"stream_stats"`
}

// ResourceUsage reports resource consumption during task execution.
type ResourceUsage struct {
	// CPUUserSeconds is the total user-mode CPU seconds consumed.
	CPUUserSeconds float64 `json:"cpu_user_seconds"`

	// CPUSystemSeconds is the total kernel-mode CPU seconds consumed.
	CPUSystemSeconds float64 `json:"cpu_system_seconds"`

	// PeakMemoryMB is the peak memory usage in megabytes.
	PeakMemoryMB float64 `json:"peak_memory_mb"`

	// DiskReadMB is the total disk read volume.
	DiskReadMB float64 `json:"disk_read_mb"`

	// DiskWriteMB is the total disk write volume.
	DiskWriteMB float64 `json:"disk_write_mb"`

	// NetworkRxMB is the total network receive volume.
	NetworkRxMB float64 `json:"network_rx_mb"`

	// NetworkTxMB is the total network transmit volume.
	NetworkTxMB float64 `json:"network_tx_mb"`
}

// ArtifactBundle describes the compressed output artifact.
type ArtifactBundle struct {
	// FileName is the name of the artifact archive.
	FileName string `json:"file_name"`

	// TotalBytes is the compressed archive size.
	TotalBytes int64 `json:"total_bytes"`

	// SHA256 is the hash of the compressed archive for integrity verification.
	SHA256 string `json:"sha256"`

	// ContainedFiles lists the files inside the archive.
	ContainedFiles []string `json:"contained_files"`

	// UncompressedBytes is the total size before compression.
	UncompressedBytes int64 `json:"uncompressed_bytes"`
}

// StreamStats reports Channel A streaming statistics.
type StreamStats struct {
	// TotalFramesSent is the total number of stream frames sent.
	TotalFramesSent uint64 `json:"total_frames_sent"`

	// TotalBytesSent is the total bytes of stream data sent.
	TotalBytesSent uint64 `json:"total_bytes_sent"`

	// StdoutLines is the count of stdout lines.
	StdoutLines uint64 `json:"stdout_lines"`

	// StderrLines is the count of stderr lines.
	StderrLines uint64 `json:"stderr_lines"`

	// DroppedFrames is the number of frames dropped due to buffer overflow.
	DroppedFrames uint64 `json:"dropped_frames"`
}
